INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('530e14b5-9fd8-4226-8545-f5f3f56ece49', 'Domicilio del Contrato', E'"Centro Comercial ANTEA LIFE STYLE CENTER", número 12,401 de la Carretera San Luis Potosí-Querétaro, "Local Comercial", identificado como L 207 ( "L" doscientos siete), Colonia El Salitre, Ejido Jurica, C.P. 76127, en el Municipio de Querétaro, Estado de Querétaro.\nLocal número L 207', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('530e14b5-9fd8-4226-8545-f5f3f56ece49', 'Fecha de Apertura', '13 de septiembre de 2024', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('530e14b5-9fd8-4226-8545-f5f3f56ece49', 'Fecha de Firma del Contrato', '11 de diciembre de 2023', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('530e14b5-9fd8-4226-8545-f5f3f56ece49', 'Late Fees', '11', '4', 'INTERESES MORATORIOS', E'- If the tenant is late in paying rent, they must pay the landlord late interest.\n- The interest is calculated daily.\n- The rate is twice the 28-day Interbank Equilibrium Interest Rate published by the Bank of Mexico.\n- The rate used is from the business day before the tenant was late.', 'En caso de retraso en el pago de la Renta, la Arrendataria se obliga a pagar a la Arrendadora por concepto de intereses moratorios, por cada día que la Arrendataria permanezca en mora, el equivalente a la cantidad que resulte de multiplicar por 2 (dos) la Tasa de Interés Interbancaria de Equilibrio a plazo de 28 días publicada por el Banco de México en el DOF el día hábil inmediato anterior al de la fecha en que la Arrendataria incurra en mora de la obligación de pago correspondiente conforme al presente Contrato.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('530e14b5-9fd8-4226-8545-f5f3f56ece49', 'Percentage Rent', '8', '2', 'CONTRAPRESTACIÓN', E'- If 9% of the Net Sales for the month is more than the Fixed Monthly Rent, the tenant must pay the landlord the difference plus applicable VAT as Variable Rent.\n- If 9% of the Net Sales is less than the Fixed Monthly Rent, the tenant does not pay any additional amount as Variable Rent for that month.', E'Adicionalmente, si el 9% (nueve por ciento) de las VENTAS NETAS (conforme la definición señalada más adelante) durante el mes que corresponda es superior a la Renta Mensual Fija, la Arrendataria deberá pagar a la Arrendadora, además de lo que hubiese pagado por concepto de Renta Mensual Fija, el total de dicha diferencia más el Impuesto al Valor Agregado correspondiente, misma que se considerará como Renta Variable.\n\nSi el 9% (nueve por ciento) de dichas Ventas Netas durante el mes que corresponda es inferior a la Renta Mensual Fija, la Arrendataria no pagará en ese mes diferencia alguna a "LA ARRENDADORA" por concepto de Renta Variable.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('530e14b5-9fd8-4226-8545-f5f3f56ece49', 'Common Area Maintenance Charges', '9', '2 Bis', 'CUOTA DE MANTENIMIENTO Y PUBLICIDAD', E'- The tenant must pay the landlord a monthly fee for maintenance and advertising.\n- The maintenance fee is 15% of the current monthly rent.\n- The advertising fee is 5% of the current fixed monthly rent.\n- These fees are calculated based on the fixed monthly rent plus applicable VAT.\n- Payments must be made within the first 10 business days of the month.\n- Payments should be deposited into the bank account specified in Clause Three of the contract.', 'En tales condiciones, La Arrendataria se obliga a cubrir mensualmente a La Arrendadora, una cuota equivalente al 15% (quince por ciento) del importe de la Renta Mensual vigente, en la fecha del pago por concepto de gastos de mantenimiento, y otra cantidad equivalente a 5% (cinco por ciento) del importe de la Renta Mensual Fija vigente en la fecha del pago por concepto de cuota de publicidad ("Cuota de Mantenimiento y Publicidad"). Dichos porcentajes se deben calcular sobre el importe de la Renta Mensual Fija, según lo pactado en la Cláusula Segunda del presente contrato, más el correspondiente Impuesto al Valor Agregado, y deberán ser pagados a La Arrendadora dentro de los primeros 10 (diez) días hábiles en la cuenta bancaria especificada en la Cláusula Tercera del presente contrato.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('530e14b5-9fd8-4226-8545-f5f3f56ece49', 'Incremento de Renta', '8', '2', 'CONTRAPRESTACIÓN', E'- The fixed monthly rent and the maintenance and advertising fee will increase every January, starting in 2025.\n- The increase will be based on the market values for the property and a specific adjustment factor.\n- The adjustment factor is calculated by dividing the most recent National Consumer Price Index (INPC) before the rent increase by the INPC from the start of the lease or the last adjustment.', E'La Renta Mensual Fija, y la Cuota de Mantenimiento y Publicidad pactadas en esta Cláusula será incrementada en forma ANUAL, en el mes de enero de cada año, a partir del 01 de enero del 2025 aplicando a dichos conceptos del último mes anterior al ajuste, el factor a que se refiere el párrafo siguiente, así como tomando en consideración los Valores de Mercado aplicables al inmueble en materia de arrendamiento que en su momento rijan y que se encuentren vigentes.\n\nEl factor de ajuste para efectos del párrafo anterior se calculará dividiendo el último INPC publicado en fecha anterior al del mes previo al incremento de la Renta Mensual Fija y Cuota de Mantenimiento y Publicidad entre el último publicado al mes de inicio del arrendamiento o al mes del último ajuste, según corresponda.');
