INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('feb4d448-41e2-46f4-beb2-a3c6c00141d9', 'Late Fees', '3', '4', 'CONTRAPRESTACIÓN', E'- If the subtenant doesn''t pay rent within the first 10 days of the month, late interest will be added starting on the 11th day.\n- The late interest rate is three times the Interbank Equilibrium Interest Rate published by Banxico, spread over the time of delay.\n- Alternatively, a 4% monthly interest rate may apply, also spread over the delay period.\n- Any payments made by the subtenant will first cover the interest, and any remaining amount will go towards the overdue rent.', E'Sobre el entendido que a partir del onceavo día se acumularán al saldo insoluto, intereses moratorios, calculados a razón de la tasa anualizada que resulte de multiplicar por 3 (tres) la TASA DE INTERES INTERBANCARIA DE EQUILIBRIO, publicada mensualmente por Banxico, prorrateado durante el tiempo que permanezca en mora; en caso de existir adeudos por rentas o intereses, EL SUBARRENDATARIO reconoce y acepta que cualquier cantidad que abonase se aplicará primero a cubrir los intereses, y en su caso, el restante a cuenta de las rentas adeudadas.\n\nEn caso de que EL SUBARRENDATARIO no realice el pago de la Renta dentro de los primeros diez días naturales del mes que corresponda, sobre el entendido que a partir del décimo primer día se acumularán al saldo insoluto, intereses moratorios, a razón del 4% (cuatro por ciento) mensual, prorrateado durante el tiempo que permanezca en mora; en caso de existir adeudos por rentas o intereses, EL SUBARRENDATARIO reconoce y acepta que cualquier cantidad que abonase se aplicará primero a cubrir los intereses, y en su caso, el restante a cuenta de las rentas adeudadas.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('feb4d448-41e2-46f4-beb2-a3c6c00141d9', 'Common Area Maintenance Charges', '3', '4', 'CONTRAPRESTACIÓN', E'- The subtenant must pay a maintenance fee equal to 10% of the current monthly rent.\n- This fee starts when the business begins operations in the commercial area.\n- The fee will include the applicable value-added tax or any future tax that replaces it.', 'Adicionalmente EL SUBARRENDATARIO deberá cubrir una cuota de mantenimiento equivalente al 10% de la renta mensual actual vigente, dicha cantidad se comenzará a pagar a partir de la apertura o inicio de operaciones del negocio que operará en EL ÁREA COMERCIAL, En el entendido que a dicha cantidad se le agregará el correspondiente impuesto al valor agregado o el impuesto que en su momento llegare a sustituirlo.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('feb4d448-41e2-46f4-beb2-a3c6c00141d9', 'Incremento de Renta', '4', '5', 'AUMENTO DE LA RENTA', E'- The monthly rent for subleasing the commercial area will increase annually every January.\n- The first increase will occur in January 2027.\n- The increase will match the rise in the National Consumer Price Index published by INEGI or any replacement index measuring inflation in Mexico.\n- Annual increases are capped at a maximum of 8% of the current rent amount.', 'El importe de la contraprestación mensual por el subarrendamiento de EL ÁREA COMERCIAL se incrementará Anualmente, durante los meses de enero de cada año, siendo el primer incremento hasta el mes de enero del año 2027, en la misma proporción en que aumente el Índice Nacional de Precios al Consumidor que publique el INEGI (o el indice que lo sustituyere para medir la inflación en los Estados Unidos Mexicanos), en la inteligencia de que dichos aumentos anuales no podrán ser mayor a un 8% del valor de la contraprestación vigente que opere en dicho periodo.');
