INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('dc5ebe12-171d-4b44-b456-a5e190fc9080', 'Fecha de Apertura', '25 de enero de 2020', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('dc5ebe12-171d-4b44-b456-a5e190fc9080', 'Late Fees', '9', '5', 'INTERESES MORATORIOS', E'- If the tenant is late in making any payment, they must pay late interest on the unpaid balance.\n- The interest rate is twice the 28-day Interbank Equilibrium Interest Rate (TIIE) published by the Bank of Mexico.\n- Interest is calculated for each day of delay.', 'En caso de mora en el pago de cualquier prestación a cargo del Arrendatario, éste último se obliga a pagar intereses moratorios sobre saldos insolutos por cada día de retraso, a una tasa anual equivalente a la cantidad que resulte de multiplicar por 2.0 (dos) veces de Interés Interbancaria de Equilibrio (TIIE) a 28 días publicada por el Banco de México en el Diario Oficial de la Federación.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('dc5ebe12-171d-4b44-b456-a5e190fc9080', 'Common Area Maintenance Charges', '10', '6', 'REGLAMENTO Y MANTENIMIENTO', E'- El arrendatario debe pagar puntualmente las cuotas de mantenimiento desde la fecha de inicio, excepto durante el periodo de gracia.\n- Los pagos deben hacerse en la cuenta indicada en el contrato o en otra que la arrendadora informe por escrito.\n- Las cuotas de mantenimiento incluyen el Impuesto al Valor Agregado (IVA).\n- Las cuotas se basan en un presupuesto anual del centro comercial, dividido en 12 meses, con una cuota fija durante 11 meses y un ajuste en el mes 12.\n- El arrendatario debe depositar un fondo de reserva equivalente a tres meses de cuotas de mantenimiento antes de la fecha de inicio.\n- El fondo de reserva garantiza que el local se entregue sin deudas de mantenimiento y no se considera pago adelantado ni genera intereses.\n- El fondo de reserva se ajusta si cambian las cuotas de mantenimiento y se devuelve al arrendatario 60 días hábiles después de entregar el local, si no hay deudas.\n- Las cuotas de mantenimiento no superarán el 10% del costo de la renta mensual.', E'Igualmente, el Arrendatario se obliga a cubrir puntualmente, a partir de la Fecha de Inicio, salvo por lo previsto para el periodo de gracia en este contrato, los pagos por concepto de cuotas de mantenimiento, mismas que deberán ser pagadas en la cuenta señalada en la carátula de este Contrato o en cualquier otra que le indique la Arrendadora por escrito de tiempo en tiempo a la Arrendataria más el Impuesto al Valor Agregado correspondiente. Dichas cuotas de mantenimiento están soportadas conforme a un prorrateo de expensas, siguiendo un presupuesto anual del Centro Comercial aprobado por los condóminos, conforme y bajo la normatividad del Reglamento, de este presupuesto anual se divide en 12 (doce) meses y se cobra una cuota fija durante 11 (once) meses, y en el mes numero 12 (doce) se ajustan las cantidades, por lo que podrá ser mayor o menor la cantidad del último mes. En este mismo sentido, el Arrendatario se obliga a depositar a la administración del Centro Comercial, en una sola exhibición, por concepto de fondo de reserva para el cumplimiento de sus obligaciones conforme a esta cláusula, una cantidad equivalente a 3-tres meses de aportaciones de cuotas de mantenimiento (el "Fondo de Reserva"). Dicho Fondo de Reserva deberá ser entregado a la administración del Centro Comercial antes de la Fecha de Inicio. El referido Fondo de Reserva se constituye para garantizar la entrega del Local sin adeudas por concepto de cuotas de mantenimiento y cualquier otra cantidad adeudada por el Arrendatario. Dicho Fondo de Reserva (i) no se considera como pago de aportaciones de cuotas de mantenimiento futuras, (ii) ni como pago por adelantado de servicios o para cubrir cualquier otro adeudo que pudiere tener el Arrendatario en los términos de este Contrato, y (ii) no generarȧ intereses a favor del Arrendatario. La cantidad entregada como Fondo de Reserva se actualizará al cambiar por cualquier concepto el monto de las aportaciones de cuotas de mantenimiento y le será reintegrada al Arrendatario al entregar el Local a la Arrendadora, en un plazo de 60 dias hábiles contados a partir de la entrega de la posesión del Local a la Arrendadora y posterior a la firma del convenio de terminación de este Contrato, en caso de que no tuviere adeudo alguno a esa fecha.\n\nLas cuotas de mantenimiento, en ningún caso excederá del 10% (diez por ciento) del costo de la renta mensual.');
